import{_ as t,o,c as i,ak as l}from"./chunks/framework.Bh2SsxPX.js";const g=JSON.parse('{"title":"Util 工具","description":"","frontmatter":{"title":"Util 工具","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/util/index.md","filePath":"posts/docs/util/index.md","lastUpdated":1777878001000}'),n={name:"posts/docs/util/index.md"};function c(d,e,r,a,s,p){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="anvillib-util-工具库文档" tabindex="-1">AnvilLib Util 工具库文档 <a class="header-anchor" href="#anvillib-util-工具库文档" aria-label="Permalink to “AnvilLib Util 工具库文档”">​</a></h1><p>AnvilLib Util 是一个 Minecraft 模组开发辅助库，提供大量常用工具类、序列化接口、UI 滚动辅助、谓词系统及组件渲染工具。</p><p>本目录包含以下模块的文档：</p><ul><li><strong>核心工具</strong>：<code>Lazy</code>、集合与列表工具、数学工具、通用工具</li><li><strong>方块形状工具</strong>：<code>ShapeUtil</code>（含多线程合并、旋转镜像等）</li><li><strong>物品/物品栈工具</strong>：<code>InventoryUtil</code>、<code>UnlimitedItemStack</code></li><li><strong>谓词系统</strong>：<code>NbtPredicate</code>、<code>ItemPredicate</code>、<code>BlockStatePredicate</code> 等</li><li><strong>UI 滚动</strong>：<code>Scrollable</code></li><li><strong>环境与分发</strong>：<code>DistExecutor</code>、<code>ClientTickRecorder</code></li><li><strong>文本组件</strong>：<code>ComponentUtil</code>、<code>MultilineComponentHelper</code>、<code>IComponentInfo</code></li><li><strong>空值安全</strong>：<code>NonNull*</code> / <code>Nullable*</code> 函数式接口与注解</li></ul><p>点击左侧目录浏览各模块详细说明。</p>',5)])])}const m=t(n,[["render",c]]);export{g as __pageData,m as default};
